@Tag("managedStorageLive") @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class CatalogRelationLiveTest {
 ManagedLiveFixture f;String ds;
 @BeforeAll void start()throws Exception{f=new ManagedLiveFixture(CatalogLiveTest.Settings.class);var loaded=f.bean(ExternalDataSources.class);f.bean(ConfigurationDeploymentService.class).allow(loaded.environment(),loaded.bootId(),0,UUID.randomUUID(),"fixture",false);f.bean(DataSourceSyncService.class).synchronize(loaded);ds=f.database().queryForObject("SELECT DATA_SOURCE_ID::text FROM AI_ADMIN_DATA_SOURCE WHERE DATA_SOURCE_KEY='orders'",String.class);var j=f.database();j.update("INSERT INTO SYS_API(API_URL,API_NM,API_DESC,ACTION_CD) VALUES ('/api/admin/service/catalog/getRelationList','관계 목록','관계 목록','READ') ON CONFLICT DO NOTHING");j.update("INSERT INTO SYS_MENU_API(MENU_CD,API_URL) VALUES ('HUB_CATALOG','/api/admin/service/catalog/getRelationList') ON CONFLICT DO NOTHING");f.bean(com.aiagent.domain.authz.service.ApiAuthorityRegistry.class).load();j.update("INSERT INTO SYS_CODE_GROUP(GRP_CD,GRP_NM) VALUES ('DBMS_DATA_TYPE','자료형 시험') ON CONFLICT DO NOTHING");for(String ref:List.of("PARENT","NATIVE_TYPE"))j.update("INSERT INTO SYS_CODE_GRP_REF(GRP_CD,REF_CD,REF_NM) VALUES ('DBMS_DATA_TYPE',?,?) ON CONFLICT DO NOTHING",ref,ref);for(String code:List.of("REL_INT","REL_OTHER")){j.update("INSERT INTO SYS_CODE(GRP_CD,DTL_CD,DTL_NM,USE_YN) VALUES ('DBMS_DATA_TYPE',?,?,'Y')",code,"code.DBMS_DATA_TYPE."+code);j.update("INSERT INTO SYS_CODE_REF(GRP_CD,DTL_CD,REF_CD,REF_VAL) VALUES ('DBMS_DATA_TYPE',?,'PARENT','POSTGRESQL'),('DBMS_DATA_TYPE',?,'NATIVE_TYPE','bigint')",code,code);}}
 @AfterAll void stop(){if(f!=null)f.close();}
 record Asset(String id,String revision,List<String> columns){}
 ManagedCommand command(String id,String rev,String scope,Map<String,Object> values){return new ManagedCommand(UUID.randomUUID().toString(),id,rev,scope,values,"관계 저장 실제 검증");}
 Map<String,Object> master(String name){return new LinkedHashMap<>(Map.of("dataSourceId",ds,"databaseName","managed040_slice","schemaName","public","objectName",name,"objectType","TABLE","businessName",name,"description","관계 시험 정의","useYn",false,"pkName","pk_"+name));}
 Asset asset(String name,boolean verified)throws Exception{var m=master(name);String id=f.adminCall("catalog","saveCreate",command(null,null,"MASTER",m),200).path("targets").get(0).path("targetId").asText();var rows=new ArrayList<Map<String,Object>>();for(int n=1;n<=2;n++)rows.add(Map.of("clientKey","c"+n,"columnName","id_"+n,"ordinalPosition",n,"sourceTypeCode","REL_INT","sourceType","bigint","primaryKeySummary","YES","pkPosition",n));f.adminCall("catalog","saveChange",command(id,"1","COLUMNS",Map.of("columns",rows)),200);if(verified){m.put("pkReview","VERIFIED");m.put("pkEvidence","전체 두 컬럼의 유일성을 설계서와 대조");f.adminCall("catalog","saveChange",command(id,"2","MASTER",m),200);}var columns=f.adminCall("catalog","getOne",Map.of("id",id),200).path("values").path("columns");return new Asset(id,verified?"3":"2",List.of(columns.get(0).path("columnId").asText(),columns.get(1).path("columnId").asText()));}
 Map<String,Object> relation(Asset left,Asset right){var r=new LinkedHashMap<String,Object>();r.put("clientKey",UUID.randomUUID().toString());r.put("relationName","주문 고객 관계");r.put("leftCatalogId",left.id());r.put("leftRevision",left.revision());r.put("rightCatalogId",right.id());r.put("rightRevision",right.revision());r.put("leftRole","주문");r.put("rightRole","고객");r.put("cardinality","N:1");r.put("description","두 컬럼을 모두 연결한다. 미매칭 주문과 주문 없는 고객이 있을 수 있다.");r.put("reviewStatus","VERIFIED");r.put("pairs",List.of(Map.of("position",2,"leftColumnId",left.columns().get(1),"rightColumnId",right.columns().get(1)),Map.of("position",1,"leftColumnId",left.columns().get(0),"rightColumnId",right.columns().get(0))));return r;}
 Map<String,Object> editable(tools.jackson.databind.JsonNode node){var result=new LinkedHashMap<String,Object>();var mapper=tools.jackson.databind.json.JsonMapper.builder().build();for(String key:List.of("relationId","relationName","leftCatalogId","leftRevision","rightCatalogId","rightRevision","leftRole","rightRole","cardinality","description","reviewStatus"))if(node.has(key)&&!node.path(key).isNull())result.put(key,mapper.convertValue(node.path(key),Object.class));var pairs=new ArrayList<Map<String,Object>>();for(var pair:node.path("pairs"))pairs.add(Map.of("position",pair.path("position").asInt(),"leftColumnId",pair.path("leftColumnId").asText(),"rightColumnId",pair.path("rightColumnId").asText()));result.put("pairs",pairs);return result;}
 @Test @DisplayName("TC-0111 TC-0113 TC-01110 소유 전체 저장·양쪽 역조회·정확 과거 판·이력 실패·원명령")
 void fullSaveExactRevisionsAndAtomicHistory()throws Exception{
  var a=asset("rel_a",true);var b=asset("rel_b",true);var draft=relation(a,b);var c=command(a.id(),"3","RELATIONSHIPS",Map.of("relations",List.of(draft)));var result=f.adminCall("catalog","saveChange",c,200);assertThat(f.adminCall("catalog","saveChange",c,200)).isEqualTo(result);String relation=result.path("memberMappings").get(0).path("memberId").asText();assertThat(result.path("memberMappings").get(0).path("kind").asText()).isEqualTo("RELATION");
  var detail=f.adminCall("catalog","getOne",Map.of("id",a.id()),200);var saved=detail.path("values").path("relations").get(0);assertThat(saved.path("relationId").asText()).isEqualTo(relation);assertThat(saved.path("reviewStatus").asText()).isEqualTo("VERIFIED");assertThat(saved.path("leftRevision").asText()).isEqualTo("4");assertThat(saved.path("rightRevision").asText()).isEqualTo("3");assertThat(saved.path("pairs").get(0).path("position").asInt()).isEqualTo(1);assertThat(saved.path("regId").asText()).isEqualTo("admin");assertThat(saved.path("leftColumns").size()).isEqualTo(2);
  var reverse=f.adminCall("catalog","getRelatedJoins",Map.of("id",b.id()),200);assertThat(reverse.path("state").asText()).isEqualTo("READY");assertThat(reverse.path("rows").get(0).path("ownerCatalogId").asText()).isEqualTo(a.id());assertThat(reverse.path("rows").get(0).path("matchedSides").get(0).asText()).isEqualTo("RIGHT");
  var filter=Map.of("conditions",List.of(Map.of("field","dataSourceId","op","eq","value",ds),Map.of("field","keyword","op","contains","value","주문 고객")),"page",Map.of("page",0,"size",20));assertThat(f.adminCall("catalog","getRelationList",filter,200).path("content").size()).isEqualTo(1);
  var newer=master("rel_b");newer.put("description","다음 판 설명");f.adminCall("catalog","saveChange",command(b.id(),"3","MASTER",newer),200);assertThat(f.adminCall("catalog","getOne",Map.of("id",a.id()),200).path("values").path("relations").get(0).path("rightRevision").asText()).isEqualTo("3");
  var changed=editable(saved);changed.put("description","새 업무 설명. 양방향 누락 가능성 재확인");var update=command(a.id(),"4","RELATIONSHIPS",Map.of("relations",List.of(changed)));
  f.database().execute("CREATE FUNCTION fx_relation_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '관계 이력 실패'; END $$");f.database().execute("CREATE TRIGGER fx_relation_fail BEFORE INSERT ON AI_ADMIN_CATALOG_JOIN_PAIR_HIST FOR EACH ROW EXECUTE FUNCTION fx_relation_fail()");f.adminCall("catalog","saveChange",update,503);assertThat(f.database().queryForObject("SELECT REVISION FROM AI_ADMIN_CATALOG WHERE CATALOG_ID=?",Long.class,Long.valueOf(a.id()))).isEqualTo(4);f.database().execute("DROP TRIGGER fx_relation_fail ON AI_ADMIN_CATALOG_JOIN_PAIR_HIST");f.adminCall("catalog","saveChange",update,200);var after=f.adminCall("catalog","getOne",Map.of("id",a.id()),200).path("values").path("relations").get(0);assertThat(after.path("regDtm")).isEqualTo(saved.path("regDtm"));assertThat(after.path("pairs").get(0).path("regDtm")).isEqualTo(saved.path("pairs").get(0).path("regDtm"));assertThat(after.path("reviewStatus").asText()).isEqualTo("UNKNOWN");
  assertThat(f.database().queryForObject("SELECT DESCRIPTION FROM AI_ADMIN_CATALOG_RELATION_HIST WHERE CATALOG_ID=? AND RELATION_ID=? ORDER BY HISTORY_NO LIMIT 1",String.class,Long.valueOf(a.id()),Long.valueOf(relation))).isEqualTo(draft.get("description"));
  var foreign=editable(after);f.adminCall("catalog","saveChange",command(b.id(),"4","RELATIONSHIPS",Map.of("relations",List.of(foreign))),409);f.adminCall("catalog","saveChange",command(a.id(),"4","RELATIONSHIPS",Map.of("relations",List.of())),409);
  f.database().update("INSERT INTO SYS_ROLE_MENU_AUTH VALUES ('READER040','HUB_CATALOG','READ') ON CONFLICT DO NOTHING");var reader=f.login("reader040");assertThat(reader.call("POST","/api/admin/service/catalog/saveChange",command(a.id(),"5","RELATIONSHIPS",Map.of("relations",List.of()))).statusCode()).isEqualTo(403);
 }
 @Test @DisplayName("TC-0112 TC-0116 TC-0117 자기조인 역할·전체 키·자료형/소유/정확 판 거부")
 void validationAndSelfJoin()throws Exception{
  var a=asset("rel_self",true);var self=relation(a,a);self.put("cardinality","1:1");f.adminCall("catalog","saveChange",command(a.id(),"3","RELATIONSHIPS",Map.of("relations",List.of(self))),200);var reverse=f.adminCall("catalog","getRelatedJoins",Map.of("id",a.id()),200);assertThat(reverse.path("rows").size()).isEqualTo(1);assertThat(reverse.path("rows").get(0).path("matchedSides").size()).isEqualTo(2);
  var current=f.adminCall("catalog","getOne",Map.of("id",a.id()),200).path("values").path("relations").get(0);var a4=new Asset(a.id(),"4",a.columns());var partial=relation(a4,a4);partial.put("pairs",List.of(Map.of("position",1,"leftColumnId",a.columns().get(0),"rightColumnId",a.columns().get(0))));f.adminCall("catalog","saveChange",command(a.id(),"4","RELATIONSHIPS",Map.of("relations",List.of(editable(current),partial))),200);var both=f.adminCall("catalog","getOne",Map.of("id",a.id()),200).path("values").path("relations");assertThat(both.size()).isEqualTo(2);assertThat(both.get(1).path("reviewStatus").asText()).isEqualTo("UNKNOWN");
  var b=asset("rel_unknown",false);var incomplete=relation(b,b);incomplete.put("pairs",List.of(Map.of("position",1,"leftColumnId",b.columns().get(0),"rightColumnId",b.columns().get(0))));f.adminCall("catalog","saveChange",command(b.id(),"2","RELATIONSHIPS",Map.of("relations",List.of(incomplete))),200);assertThat(f.adminCall("catalog","getOne",Map.of("id",b.id()),200).path("values").path("relations").get(0).path("reviewStatus").asText()).isEqualTo("UNKNOWN");
  var c=asset("rel_types",true);var bad=relation(c,a);bad.put("rightRevision","999");f.adminCall("catalog","saveChange",command(c.id(),"3","RELATIONSHIPS",Map.of("relations",List.of(bad))),409);bad=relation(c,a);bad.put("leftCatalogId",a.id());f.adminCall("catalog","saveChange",command(c.id(),"3","RELATIONSHIPS",Map.of("relations",List.of(bad))),409);
  f.database().update("UPDATE SYS_CODE SET USE_YN='N' WHERE GRP_CD='DBMS_DATA_TYPE' AND DTL_CD='REL_INT'");f.adminCall("catalog","saveChange",command(c.id(),"3","RELATIONSHIPS",Map.of("relations",List.of(relation(c,a)))),409);f.database().update("UPDATE SYS_CODE SET USE_YN='Y' WHERE GRP_CD='DBMS_DATA_TYPE' AND DTL_CD='REL_INT'");
  f.database().update("UPDATE AI_ADMIN_CATALOG_COLUMN SET SOURCE_TYPE_CD='REL_OTHER' WHERE CATALOG_ID=?",Long.valueOf(c.id()));f.adminCall("catalog","saveChange",command(c.id(),"3","RELATIONSHIPS",Map.of("relations",List.of(relation(c,a)))),409);
 }
 @Test @DisplayName("TC-01110 관계 감사 migration 적용·rollback·재적용")
 void migrationRoundTrip()throws Exception{String schema="catalog_migration011_"+UUID.randomUUID().toString().replace("-","");try(var connection=java.sql.DriverManager.getConnection(System.getenv("MANAGED_TEST_JDBC"),System.getenv("MANAGED_TEST_USER"),System.getenv().getOrDefault("MANAGED_TEST_PASSWORD",""))){connection.createStatement().execute("CREATE SCHEMA "+schema);connection.setSchema(schema);try(var migration=new liquibase.Liquibase("db/catalog011-migration.yaml",new liquibase.resource.ClassLoaderResourceAccessor(),new liquibase.database.jvm.JdbcConnection(connection))){migration.update(new liquibase.Contexts());columns(connection,18);migration.rollback(1,"");columns(connection,0);migration.update(new liquibase.Contexts());columns(connection,18);}}}
 void columns(java.sql.Connection connection,int expected)throws Exception{try(var result=connection.createStatement().executeQuery("SELECT count(*) FROM information_schema.columns WHERE table_schema=current_schema() AND table_name IN ('ai_admin_catalog_relation','ai_admin_catalog_relation_hist','ai_admin_catalog_join_pair','ai_admin_catalog_join_pair_hist') AND column_name IN ('relation_nm','reg_id','reg_dtm','mod_id','mod_dtm')")){result.next();assertThat(result.getInt(1)).isEqualTo(expected);}}
}
